export function getExcelTimeline(options: {
  product: string;
  byproduct?: string;
  locationLabel?: string;
  locationKind?: string;
  rateType?: string;
  range?: 'week' | 'month' | 'quarter' | 'day' | 'year';
}): TimelineResult {
  const {
    product,
    byproduct = '',
    locationLabel = '',
    locationKind = 'pakistan',
    rateType = '',
    range = 'week',
  } = options;

  const pNorm = (product || '').toLowerCase().trim();
  const bpNorm = (byproduct || '').toLowerCase().trim();
  const locNorm = (locationLabel || '')
    .toLowerCase()
    .replace(/\s*mandi$/i, '')
    .replace(/\s*منڈی$/i, '')
    .trim();
  const rtNorm = (rateType || '')
    .toLowerCase()
    .replace(/\s*rate$/i, '')
    .replace(/\s*ریٹ$/i, '')
    .trim();

  // Candidate lookup keys ordered by specificity (mandi -> district -> province -> national)
  const keys: string[] = [];
  if (locationKind === 'mandi' && locNorm) {
    if (rtNorm) {
      if (bpNorm) keys.push(`m:${locNorm}:${pNorm}:${bpNorm}:${rtNorm}`);
      keys.push(`m:${locNorm}:${pNorm}::${rtNorm}`);
    }
    if (bpNorm) keys.push(`m:${locNorm}:${pNorm}:${bpNorm}:`);
    keys.push(`m:${locNorm}:${pNorm}::`);
  } else if (locationKind === 'district' && locNorm) {
    if (rtNorm) {
      if (bpNorm) keys.push(`d:${locNorm}:${pNorm}:${bpNorm}:${rtNorm}`);
      keys.push(`d:${locNorm}:${pNorm}::${rtNorm}`);
    }
    if (bpNorm) keys.push(`d:${locNorm}:${pNorm}:${bpNorm}:`);
    keys.push(`d:${locNorm}:${pNorm}::`);
  } else if (
    locationKind === 'province' &&
    locNorm &&
    locNorm !== 'pakistan' &&
    locNorm !== 'national'
  ) {
    if (rtNorm) {
      if (bpNorm) keys.push(`pr:${locNorm}:${pNorm}:${bpNorm}:${rtNorm}`);
      keys.push(`pr:${locNorm}:${pNorm}::${rtNorm}`);
    }
    if (bpNorm) keys.push(`pr:${locNorm}:${pNorm}:${bpNorm}:`);
    keys.push(`pr:${locNorm}:${pNorm}::`);
  }

  // National fallbacks
  if (rtNorm) {
    if (bpNorm) keys.push(`nat:${pNorm}:${bpNorm}:${rtNorm}`);
    keys.push(`nat:${pNorm}::${rtNorm}`);
  }
  if (bpNorm) keys.push(`nat:${pNorm}:${bpNorm}:`);
  keys.push(`nat:${pNorm}::`);

  let series: TimelineSeries | undefined;
  for (let i = 0; i < keys.length; i++) {
    const found = REAL_TIMELINE_INDEX[keys[i]];
    if (found) {
      series = found;
      break;
    }
  }

  if (!series) {
    series = REAL_TIMELINE_INDEX[`nat:${pNorm}::`] || {
      p: new Array(REAL_DATES_TIMELINE.length).fill(4500),
      mi: new Array(REAL_DATES_TIMELINE.length).fill(4450),
      mx: new Array(REAL_DATES_TIMELINE.length).fill(4550),
      a: new Array(REAL_DATES_TIMELINE.length).fill(0),
    };
  }

  const sliceLen =
    range === 'week' || range === 'day'
      ? 7
      : range === 'month'
        ? 30
        : range === 'year'
          ? 31
          : REAL_DATES_TIMELINE.length;

  const slicedDates = REAL_DATES_TIMELINE.slice(-sliceLen);
  const slicedPrices = series.p.slice(-sliceLen);
  const slicedMins = series.mi.slice(-sliceLen);
  const slicedMaxs = series.mx.slice(-sliceLen);
  const slicedArrivals = series.a.slice(-sliceLen);

  const latestP = slicedPrices[slicedPrices.length - 1] ?? 0;
  const latestMin = slicedMins[slicedMins.length - 1] ?? 0;
  const latestMax = slicedMaxs[slicedMaxs.length - 1] ?? 0;

  const prevP =
    slicedPrices.length >= 2
      ? slicedPrices[slicedPrices.length - 2]
      : latestP;

  let trend: 'up' | 'down' | 'stable' = 'stable';
  let trendPct = 0.0;
  if (prevP > 0 && latestP > 0) {
    const diff = latestP - prevP;
    trendPct = Math.round((Math.abs(diff) / prevP) * 1000) / 10;
    if (diff > 0.01) trend = 'up';
    else if (diff < -0.01) trend = 'down';
  }

  return {
    dates: slicedDates,
    prices: slicedPrices,
    mins: slicedMins,
    maxs: slicedMaxs,
    arrivals: slicedArrivals,
    latestMin,
    latestMax,
    latestPrice: latestP,
    trend,
    trendPct,
    matchedCount: 1,
  };
}
